const presets={nw:{p:[6,1.72,22],t:[-20,5.8,-14]},ne:{p:[-6,1.72,17],t:[20,6.1,-13]},sw:{p:[7,1.72,-13],t:[-21,8.5,18]},se:{p:[-7,1.72,-15],t:[20,7.7,16]}};
