function notice(text){$('#notice').textContent=text;$('#notice').classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('#notice').classList.remove('visible'),2700);}
function clearInput(){keys.clear();for(const k in touch)touch[k]=0;walkVel.set(0,0);drag=null;}
function renderBusinesses(c){const list=$('#business-list');list.replaceChildren();for(const b of businessData.filter(b=>b.corner===c)){const card=document.createElement('div');card.className='business-card';const a=document.createElement('a');a.textContent=b.name+' ↗';a.href=b.source;a.target='_blank';a.rel='noopener';const address=document.createElement('small');address.textContent=b.address;card.append(a,address);const statuses={closed:'Closed · December 31, 2025',opening_unconfirmed:'Sign installed · opening unconfirmed',tenant_unconfirmed:'Current tenant unconfirmed'};if(statuses[b.status]){const status=document.createElement('small');status.className='status';status.textContent=statuses[b.status];card.append(status);}const note=document.createElement('p');note.textContent=b.notes;card.append(note);list.append(card);}}
function showReference(c=selected){const r=refs[c];renderBusinesses(c);$('#reference-title').textContent=r.title;$('#reference-corner').textContent=r.corner;$('#reference-image').src=asset(r.image);$('#reference-image').alt=r.title+' — '+r.caption;$('#reference-caption').textContent=r.caption;$('#reference-notes').textContent=r.notes;$('#reference-source').href=r.source;$('#reference-extra').hidden=!r.extra;if(r.extra)$('#reference-extra').href=r.extra;document.querySelectorAll('[data-reference]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.reference===c)));$('#reference-panel').hidden=false;}
