const openAbout=()=>{clearInput();$('#about').showModal();};$('#info-button').onclick=openAbout;$('#credits-button').onclick=openAbout;$('#close-about').onclick=()=>$('#about').close();
$('#retry-button').onclick=()=>location.reload();
$('#fullscreen-button').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#app').requestFullscreen();}catch{notice('Full screen isn’t available in this browser.');}};
document.addEventListener('fullscreenchange',()=>$('#fullscreen-button').setAttribute('aria-label',document.fullscreenElement?'Exit full screen':'Enter full screen'));
function setView(c){if(!ready)return;selected=c;setMode('walk',false);const pr=presets[c];camera.position.fromArray(pr.p);const dx=pr.t[0]-pr.p[0],dz=pr.t[2]-pr.p[2];yaw=targetYaw=Math.atan2(dx,-dz);pitch=targetPitch=Math.atan2(pr.t[1]-pr.p[1],Math.hypot(dx,dz));clearInput();document.querySelectorAll('[data-corner]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.corner===c)));if(!$('#reference-panel').hidden)showReference(c);}
document.querySelectorAll('[data-corner]').forEach(b=>b.onclick=()=>setView(b.dataset.corner));
function setMode(next,reset=true){if(!ready)return;clearInput();mode=next;$('#walk-button').setAttribute('aria-pressed',String(mode==='walk'));$('#drive-button').setAttribute('aria-pressed',String(mode==='drive'));$('#speed').hidden=mode!=='drive';hood.visible=mode==='drive';$('#controls').innerHTML=mode==='drive'?'<kbd>W S</kbd> throttle / brake <span>·</span> <kbd>A D</kbd> steer <span>·</span> <kbd>SPACE</kbd> brake':'<kbd>W A S D</kbd> move <span>·</span> drag to look <span>·</span> <kbd>Q E</kbd> turn';if(reset&&next==='drive'){car=createVehicle(carWorld.spawn(camera.position.x,camera.position.z));headYaw=headPitch=0;yaw=targetYaw=car.yaw;pitch=targetPitch=0;notice('W to accelerate · S to brake, then reverse');}else if(reset){camera.position.set(car.x,1.72,car.z);yaw=targetYaw=car.yaw;pitch=targetPitch=0;}stepper.reset();}
$('#walk-button').onclick=()=>setMode('walk');$('#drive-button').onclick=()=>setMode('drive');$('#reset-button').onclick=()=>{if(mode==='drive'){car=createVehicle({x:1,z:45,yaw:0});headYaw=headPitch=0;stepper.reset();}else setView('nw');};
function down(e){if($('#about').open||$('#map-dialog').open||e.target.closest('input,textarea'))return;const k=e.key.toLowerCase();if(['w','a','s','d','q','e','arrowup','arrowdown','arrowleft','arrowright',' ','shift'].includes(k)){e.preventDefault();keys.add(k);}if(k==='r')$('#reset-button').click();if(k==='m'){clearInput();mapUI?.open();}if(k==='escape'){$('#reference-panel').hidden=true;clearInput();}}
window.addEventListener('keydown',down);window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',clearInput);document.addEventListener('visibilitychange',()=>{if(document.hidden)clearInput();});
canvas.addEventListener('pointerdown',e=>{if(!ready)return;canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);drag={x:e.clientX,y:e.clientY,id:e.pointerId};});
canvas.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.x=e.clientX;drag.y=e.clientY;if(mode==='drive'){headYaw=clamp(headYaw+dx*.003,-1.5,1.5);headPitch=clamp(headPitch-dy*.003,-.35,.7);}else{targetYaw+=dx*.003;targetPitch=clamp(targetPitch-dy*.003,-1.08,1.15);}});
canvas.addEventListener('pointerup',()=>drag=null);canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('contextmenu',e=>e.preventDefault());
document.querySelectorAll('[data-control]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);touch[b.dataset.control]=1;});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>touch[b.dataset.control]=0);});
function inputs(){return {forward:Number(keys.has('w')||keys.has('arrowup'))||touch.forward,reverse:Number(keys.has('s')||keys.has('arrowdown'))||touch.reverse,left:Number(keys.has('a'))||touch.left,right:Number(keys.has('d'))||touch.right,brake:Number(keys.has(' '))};}
const stepper=createFixedStepper(dt=>{if(mode!=='drive'||!ready||$('#about').open||$('#map-dialog').open)return;const i=inputs(),steer=(i.right||Number(keys.has('arrowright')))-(i.left||Number(keys.has('arrowleft')));const result=stepVehicle(car,{throttle:Math.abs(car.longitudinal)<13.4?i.forward:0,reverse:i.reverse,steer,brake:i.brake},dt,carWorld,baseData.driveBounds);if(result.edge)notice('Neighborhood boundary · Turn back, or press M to choose a street.');},120);
function walk(dt){const i=inputs(),turn=Number(keys.has('e')||keys.has('arrowright'))-Number(keys.has('q')||keys.has('arrowleft'));targetYaw+=turn*dt*1.25;const f=i.forward-i.reverse,s=i.right-i.left,norm=Math.max(1,Math.hypot(f,s)),speed=keys.has('shift')?4.1:1.65,tx=(Math.sin(yaw)*f+Math.cos(yaw)*s)/norm*speed,tz=(-Math.cos(yaw)*f+Math.sin(yaw)*s)/norm*speed,blend=1-Math.exp(-dt*9);walkVel.x+=(tx-walkVel.x)*blend;walkVel.y+=(tz-walkVel.y)*blend;const nx=camera.position.x+walkVel.x*dt,nz=camera.position.z+walkVel.y*dt;if(carWorld.walkable(nx,camera.position.z))camera.position.x=nx;if(carWorld.walkable(camera.position.x,nz))camera.position.z=nz;const eye=1.72+(carWorld.roadAt(camera.position.x,camera.position.z)?0:.17);camera.position.y+=(eye-camera.position.y)*Math.min(1,dt*10);}
function fail(error){console.error(error);loading.hidden=true;$('#fallback').hidden=false;$('#fallback-message').textContent='The rendered view is shown here. Try reloading, or open the model in a 3D application.';ready=false;}
async function init(){try{
 renderer=new THREE.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.AgXToneMapping;renderer.toneMappingExposure=1.06;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;
 scene=new THREE.Scene();scene.fog=new THREE.Fog('#c8c5b8',125,470);camera=new THREE.PerspectiveCamera(59,innerWidth/innerHeight,.08,650);camera.rotation.order='YXZ';
 const sky=new Sky();sky.scale.setScalar(2000);sky.material.uniforms.turbidity.value=4.7;sky.material.uniforms.rayleigh.value=1.45;sky.material.uniforms.mieCoefficient.value=.005;sky.material.uniforms.mieDirectionalG.value=.78;const sunDirection=new THREE.Vector3(.32,.48,.81).normalize();sky.material.uniforms.sunPosition.value.copy(sunDirection);scene.add(sky);
 sun=new THREE.DirectionalLight('#ffdbac',2.65);sun.position.copy(sunDirection).multiplyScalar(80);sun.castShadow=true;sun.shadow.mapSize.set(4096,4096);Object.assign(sun.shadow.camera,{left:-76,right:76,top:80,bottom:-72,near:1,far:200});sun.shadow.bias=-.00006;sun.shadow.normalBias=.012;sun.shadow.radius=3;scene.add(sun);scene.add(sun.target);scene.add(new THREE.HemisphereLight('#c3d4e0','#78664c',.65));
 const pmrem=new THREE.PMREMGenerator(renderer);pmrem.compileEquirectangularShader();
 const environment=new RGBELoader().loadAsync(asset('assets/urban_alley_01_1k.hdr')).then(hdr=>{const env=pmrem.fromEquirectangular(hdr);scene.environment=env.texture;scene.environmentIntensity=.60;hdr.dispose();pmrem.dispose();}).catch(()=>pmrem.dispose());
 const businessPromise=fetch(asset('businesses.json')).then(r=>{if(!r.ok)throw Error('Business references unavailable');return r.json();}).then(d=>businessData=d.businesses);
 const dataPromise=fetch(asset('neighborhood.json')).then(r=>{if(!r.ok)throw Error('Map geometry unavailable');return r.json();}).then(d=>{baseData=d;carWorld=createNeighborhoodWorld(d);});
 const decoder=new DRACOLoader();decoder.setDecoderPath(new URL('../vendor/draco/',import.meta.url).href);decoder.setWorkerLimit(2);const loader=new GLTFLoader();loader.setDRACOLoader(decoder);
 const gltf=await loader.loadAsync(asset('first-and-10th.glb'),ev=>{if(ev.total){const n=Math.round(ev.loaded/ev.total*88);$('#load-fill').style.width=n+'%';$('#load-message').textContent='Loading the reconstruction… '+n+'%';}});
 gltf.scene.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;const ms=Array.isArray(o.material)?o.material:[o.material];if(ms.every(m=>m.name==='store glass'))o.castShadow=false;for(const m of ms){m.envMapIntensity=.75;if(m.map)m.map.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());if(m.normalMap)m.normalScale.set(.4,.4);}}});scene.add(gltf.scene);
 const hoodGeo=new THREE.BufferGeometry();hoodGeo.setAttribute('position',new THREE.Float32BufferAttribute([-.72,.83,-1.2,.72,.83,-1.2,.70,.71,-2.12,-.70,.71,-2.12],3));hoodGeo.setIndex([0,1,2,0,2,3]);hoodGeo.computeVertexNormals();hood=new THREE.Mesh(hoodGeo,new THREE.MeshStandardMaterial({color:'#232c2c',roughness:.22,metalness:.67,side:THREE.DoubleSide}));hood.visible=false;scene.add(hood);
 for(const [x,z] of [[-16.4,-11.8],[-29.8,10.3],[-16.4,-21.3],[16.4,19.6],[-17.0,16.1]]){const glow=new THREE.PointLight('#ffc377',19,5,2);glow.position.set(x,2.25,z);scene.add(glow);}
 await Promise.all([dataPromise,environment,businessPromise]);
 neighborhood=await createNeighborhoodRenderer({scene,loader,renderer,data:baseData,core:gltf.scene,asset,onChange:()=>renderer.shadowMap.needsUpdate=true,onStatus:text=>{$('#stream-status').textContent=text;}});
 const travel=(x,z)=>{clearInput();const spawn=carWorld.spawn(x,z);car=createVehicle(spawn);camera.position.set(spawn.x,mode==='drive'?1.28:1.72,spawn.z);yaw=targetYaw=spawn.yaw;pitch=targetPitch=headYaw=headPitch=0;stepper.reset();neighborhood.update(spawn.x,spawn.z,performance.now());};
 mapUI=createNeighborhoodMap({data:baseData,onTravel:travel,getPosition:()=>({x:camera.position.x,z:camera.position.z,yaw})});
 $('#observed-count').textContent=baseData.referenceSummary.newObservedBuildings;
 $('#map-dialog').addEventListener('close',clearInput);$('#map-dialog').addEventListener('click',clearInput);
 composer=new EffectComposer(renderer);composer.addPass(new RenderPass(scene,camera));ao=new SSAOPass(scene,camera,Math.floor(innerWidth*.75),Math.floor(innerHeight*.75));ao.kernelRadius=.75;ao.minDistance=.0005;ao.maxDistance=.015;composer.addPass(ao);composer.addPass(new OutputPass());
 ready=true;setView('nw');$('#load-fill').style.width='100%';$('#load-message').textContent='Ten blocks of the East Village';neighborhood.update(camera.position.x,camera.position.z,performance.now());mapUI.refresh();loading.classList.add('finished');setTimeout(()=>loading.hidden=true,650);renderer.shadowMap.autoUpdate=false;renderer.shadowMap.needsUpdate=true;
 let last=performance.now();function frame(now){requestAnimationFrame(frame);if(!ready||document.hidden)return;const dt=clamp((now-last)/1000,0,.05);last=now;if(!$('#about').open&&!$('#map-dialog').open){if(mode==='drive'){stepper.advance(dt);camera.position.set(car.x-.29*Math.cos(car.yaw),1.28+car.pitch*.7,car.z-.29*Math.sin(car.yaw));yaw=car.yaw+headYaw;pitch=headPitch+car.pitch;hood.position.set(car.x,0,car.z);hood.rotation.y=-car.yaw;$('#speed').innerHTML=Math.round(Math.abs(car.speed)*2.23694)+' <small>MPH</small>';}else{walk(dt);const t=reduced?1:1-Math.exp(-dt*15);yaw+=wrap(targetYaw-yaw)*t;pitch+=(targetPitch-pitch)*t;}camera.rotation.set(pitch,-yaw,mode==='drive'?car.roll:0,'YXZ');}
 worldTick+=dt;mapTick+=dt;if(worldTick>.3){neighborhood.update(camera.position.x,camera.position.z,now);worldTick=0;}
 if(mapTick>.18){mapUI.refresh();const near=carWorld.nearestRoad(camera.position.x,camera.position.z),cross=(near.road.axis==='avenue'?baseData.streets:baseData.avenues).reduce((a,b)=>Math.abs(b[1]-(near.road.axis==='avenue'?camera.position.z:camera.position.x))<Math.abs(a[1]-(near.road.axis==='avenue'?camera.position.z:camera.position.x))?b:a);$('#current-street').textContent=near.road.name+' · '+cross[0];mapTick=0;}
 if(Math.hypot(camera.position.x-shadowX,camera.position.z-shadowZ)>8){shadowX=Math.round(camera.position.x/4)*4;shadowZ=Math.round(camera.position.z/4)*4;sun.target.position.set(shadowX,0,shadowZ);sun.position.copy(sunDirection).multiplyScalar(80).add(sun.target.position);sun.target.updateMatrixWorld();renderer.shadowMap.needsUpdate=true;}
 composer.render();frameTime+=dt;frameCount++;if(frameCount===150&&!optimized){if(frameTime/frameCount>.029){renderer.setPixelRatio(1);composer.setPixelRatio(1);ao.enabled=false;optimized=true;}frameTime=frameCount=0;}}
 requestAnimationFrame(frame);
 window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);composer.setSize(innerWidth,innerHeight);ao.setSize(Math.floor(innerWidth*.75),Math.floor(innerHeight*.75));});canvas.addEventListener('webglcontextlost',e=>{e.preventDefault();fail(Error('WebGL context lost'));});
 }catch(e){fail(e);}}
init();
